def printed_grid(number,ident):
    rows=GRIDS[number,ident];cells=[c for row in rows for c in row]
    return SimpleNamespace(rows=[SimpleNamespace(cells=row) for row in rows],bbox=(min(c[0] for c in cells),min(c[1] for c in cells),max(c[2] for c in cells),max(c[3] for c in cells)))
